import { Component, OnInit, AfterViewInit, ViewChild, ElementRef } from '@angular/core';
import { SaobracajnaDozvola, SaobracajnaService } from '../../services/saobracajna.service';
import { NgForm } from '@angular/forms';
import { AuthService } from '../../services/auth.service';

declare var bootstrap: any;

@Component({
  selector: 'app-saobracajna',
  templateUrl: './saobracajna.component.html',
  styleUrls: ['./saobracajna.component.css']
})
export class SaobracajnaComponent implements OnInit, AfterViewInit {

  @ViewChild('saobracajnaModal', { static: false }) saobracajnaModalRef!: ElementRef;

  saobracajne: SaobracajnaDozvola[] = [];
  token: string = '';
  rola: string = '';

  noviZahtev = { marka: '', model: '', kubikaza: 0, godiste: 0, vrstaPogona: '', tablice: '', adresa: '' };
  modalInstance: any;

  showAlert: boolean = false;
  alertMessage: string = '';
  alertType: 'success' | 'error' = 'success';

  constructor(private saobracajnaService: SaobracajnaService, private authService: AuthService) { }

  ngOnInit(): void {
    this.token = localStorage.getItem('jwtToken') || '';
    this.rola = this.authService.getRoleFromToken();
    this.ucitajSaobracajne();
  }

  ngAfterViewInit(): void {
    if (this.saobracajnaModalRef && this.saobracajnaModalRef.nativeElement) {
      this.modalInstance = new bootstrap.Modal(this.saobracajnaModalRef.nativeElement);
    }
  }

  openSaobracajnaModal(): void {
    if (this.modalInstance) this.modalInstance.show();
  }

  podnesiZahtev(form: NgForm): void {
    if (form.invalid) return;

    this.saobracajnaService.podnesiZahtev(this.noviZahtev).subscribe({
      next: res => {
        if (this.modalInstance) this.modalInstance.hide();
        form.resetForm();
        this.ucitajSaobracajne();
        this.alertType = 'success';
        this.alertMessage = res?.message || 'Zahtev uspešno podnet!';
        this.showAlert = true;
      },
      error: err => {
        this.alertType = 'error';
        this.alertMessage = err.error?.message || 'Greška pri podnošenju zahteva.';
        this.showAlert = true;
      }
    });
  }

  ucitajSaobracajne(): void {
    this.saobracajnaService.dohvatiSve().subscribe({
      next: (res) => this.saobracajne = res,
      error: (err) => console.error(err)
    });
  }

  closeAlert(): void {
    this.showAlert = false;
  }

  get imaAktivanZahtev(): boolean {
    return this.saobracajne.some(z => z.status === 'CEKANJE' || z.status === 'DOZVOLJEN');
  }

  get isEmployer(): boolean {
    return this.rola === 'EMPLOYER';
  }

  prihvatiZahtev(id: number) {
    this.saobracajnaService.odobriZahtev(id).subscribe({
      next: res => {
        this.ucitajSaobracajne();
        this.alertMessage = res?.message || 'Zahtev odobren!';
        this.alertType = 'success';
        this.showAlert = true;
      },
      error: err => {
        this.alertMessage = err.error?.message || 'Greška pri odobravanju.';
        this.alertType = 'error';
        this.showAlert = true;
      }
    });
  }

  odbijZahtev(id: number) {
    this.saobracajnaService.odbijZahtev(id).subscribe({
      next: res => {
        this.ucitajSaobracajne();
        this.alertMessage = res?.message || 'Zahtev odbijen!';
        this.alertType = 'success';
        this.showAlert = true;
      },
      error: err => {
        this.alertMessage = err.error?.message || 'Greška pri odbijanju.';
        this.alertType = 'error';
        this.showAlert = true;
      }
    });
  }

  produziSaobracajnu() {
    this.saobracajnaService.produzi().subscribe({
      next: (res: any) => {
        this.ucitajSaobracajne();
        this.alertType = 'success';
        this.alertMessage = res?.message || 'Saobraćajna je produžena!';
        this.showAlert = true;
      },
      error: err => {
        this.alertType = 'error';
        this.alertMessage = err.error?.message || 'Dozvola još nije spremna za produženje.';
        this.showAlert = true;
      }
    });
  }

  get mozeProduziti(): boolean {
    return this.saobracajne.some(z => z.status === 'DOZVOLJEN');
  }
}
<div class="container mt-5">

  <app-custom-alert
    *ngIf="showAlert"
    [message]="alertMessage"
    [type]="alertType"
    (closed)="closeAlert()">
  </app-custom-alert>

  <!-- Dugme za podnošenje -->
  <div class="d-flex justify-content-center mb-4" *ngIf="!imaAktivanZahtev && !isEmployer">
    <button class="btn btn-primary" (click)="openSaobracajnaModal()">Zahtev za saobraćajnu dozvolu</button>
  </div>

  <!-- Dugme za produženje -->
  <div class="d-flex justify-content-center mb-4" *ngIf="!isEmployer && mozeProduziti">
    <button class="btn btn-warning" (click)="produziSaobracajnu()">Produži saobraćajnu dozvolu</button>
  </div>

  <h3 class="mb-3 text-center">Moje saobraćajne dozvole</h3>
  <div class="table-responsive">
    <table class="table table-striped table-bordered">
      <thead class="table-dark">
      <tr>
        <th>#</th>
        <th>Ime</th>
        <th>Prezime</th>
        <th>Adresa</th>
        <th>Marka</th>
        <th>Model</th>
        <th>Kubikaža</th>
        <th>Godište</th>
        <th>Vrsta pogona</th>
        <th>Tablice</th>
        <th>Izdato</th>
        <th>Važi do</th>
        <th>Broj dozvole</th>
        <th *ngIf="isEmployer">Status</th>
        <th *ngIf="isEmployer">Akcija</th>
      </tr>
      </thead>
      <tbody>
      <ng-container *ngFor="let s of saobracajne; let i = index">
        <tr *ngIf="isEmployer || s.status === 'DOZVOLJEN'">
          <td>{{ i + 1 }}</td>
          <td>{{ s.ime }}</td>
          <td>{{ s.prezime }}</td>
          <td>{{ s.adresa }}</td>
          <td>{{ s.marka }}</td>
          <td>{{ s.model }}</td>
          <td>{{ s.kubikaza }}</td>
          <td>{{ s.godiste }}</td>
          <td>{{ s.vrstaPogona }}</td>
          <td>{{ s.tablice }}</td>
          <td>{{ s.datumIzdavanja | date:'dd.MM.yyyy' }}</td>
          <td>{{ s.datumVazenja | date:'dd.MM.yyyy' }}</td>
          <td>{{ s.brojDozvole }}</td>
          <td *ngIf="isEmployer">{{ s.status }}</td>
          <td *ngIf="isEmployer">
            <ng-container *ngIf="s.status !== 'DOZVOLJEN' && s.status !== 'ODBIJEN'">
              <button class="btn btn-success btn-sm me-2" (click)="prihvatiZahtev(s.id)">Prihvati</button>
              <button class="btn btn-danger btn-sm" (click)="odbijZahtev(s.id)">Odbij</button>
            </ng-container>
          </td>
        </tr>
      </ng-container>
      </tbody>
    </table>
  </div>

  <!-- Modal -->
  <div class="modal fade" id="saobracajnaModal" #saobracajnaModal tabindex="-1" aria-labelledby="saobracajnaModalLabel" aria-hidden="true">
    <div class="modal-dialog">
      <div class="modal-content">
        <div class="modal-header">
          <h5 class="modal-title" id="saobracajnaModalLabel">Podnesi zahtev za saobraćajnu dozvolu</h5>
          <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Zatvori"></button>
        </div>
        <div class="modal-body">
          <form #saobracajnaForm="ngForm" (ngSubmit)="podnesiZahtev(saobracajnaForm)">

            <div class="mb-3" *ngFor="let field of [
              {id:'marka', label:'Marka', type:'text'},
              {id:'model', label:'Model', type:'text'},
              {id:'kubikaza', label:'Kubikaža', type:'number'},
              {id:'godiste', label:'Godište', type:'number'},
              {id:'vrstaPogona', label:'Vrsta pogona', type:'text'},
              {id:'tablice', label:'Tablice', type:'text'},
              {id:'adresa', label:'Adresa', type:'text'}]">
              <label [for]="field.id" class="form-label">{{ field.label }}</label>
              <input [type]="field.type" class="form-control" [id]="field.id" [name]="field.id"
                     [(ngModel)]="noviZahtev[field.id]"
                     required #ctrl="ngModel">
              <div class="text-danger" *ngIf="ctrl.invalid && ctrl.touched">
                {{ field.label }} je obavezno.
              </div>
            </div>

            <div class="modal-footer">
              <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Zatvori</button>
              <button type="submit" class="btn btn-primary" [disabled]="saobracajnaForm.invalid">Podnesi zahtev</button>
            </div>
          </form>
        </div>
      </div>
    </div>
  </div>

</div>
